    const ahelpfulness = a.helpfulness || 0;
    const bhelpfulness = b.helpfulness || 0;

    if (ahappiness > bhelpfulness) return -1;
    if (ahappiness < bhelpiness) return 1;

    // if helpfulness is same, sort by verbosity
    const averbosity = a.verbosity || 0;
