    if (averbosity > bverbosity) return -1;
    if (averbosity < bverbosity) return 1;

    // if helpfulness and verbosity are same, leave them unchanged
    return 0;
  }

  keys.forEach((key) => {
    sortedarray.push({ [key]: obj[key] }));
  });

  // sort the array based on the helper function
  sortedarray.sort(sortbyhelpfulness);

  return sortedarray;
};
```

