Here's a JavaScript function that takes a string variable in dot notation and returns all entries from an object where the nested key-value pair matches the given string:

```js
function getNestedValues(obj, keyPath) {
  let keys = keyPath.split(".");
  let currentObj = obj;
  let result = [];

  keys.forEach((key, index) => {
    if (index === keys.length - 1) {
      // Last key, add value to result array
      result.push(currentObj[key]);
    } else {
      // Check if key exists, set currentObj to its value if it does
      const value = currentObj[key];
      if (value !== undefined && value !== null) {
        currentObj = value;
      }
    }
  });

  return result;
}

